import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.CoXsll4d.js";const m=JSON.parse('{"title":"Plan de cours","description":"","frontmatter":{},"headers":[],"relativePath":"plan-cours/index.md","filePath":"plan-cours/index.md"}'),n={name:"plan-cours/index.md"};function s(i,e,l,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="plan-de-cours" tabindex="-1">Plan de cours <a class="header-anchor" href="#plan-de-cours" aria-label="Permalink to &quot;Plan de cours&quot;">​</a></h1><h2 id="intention" tabindex="-1">Intention <a class="header-anchor" href="#intention" aria-label="Permalink to &quot;Intention&quot;">​</a></h2><p>Vous savez programmer. Vous utilisez déjà l&#39;IA, souvent en copiant une erreur dans un chat et en recollant la réponse. Ce cours transforme cette habitude en <strong>pratique professionnelle</strong> : savoir ce que le modèle voit, lui donner le bon contexte, le laisser travailler en boucle avec de quoi vérifier son travail, le guider par une spécification, puis coordonner plusieurs agents, tout en restant responsable du code livré.</p><p>L&#39;idée qui traverse les quatre séances : passer de <strong>« l&#39;IA écrit mon code »</strong> à <strong>« je dirige un agent et je vérifie son travail »</strong>.</p><h2 id="deroulement" tabindex="-1">Déroulement <a class="header-anchor" href="#deroulement" aria-label="Permalink to &quot;Déroulement&quot;">​</a></h2><p>Quatre séances de 3 heures, du plus fondamental au plus avancé :</p><table tabindex="0"><thead><tr><th>Séance</th><th>Date</th><th>Thème</th></tr></thead><tbody><tr><td><a href="/IA101/seances/01-comprendre-la-machine">1</a></td><td>Lundi 30 novembre</td><td>Comprendre la machine et bien formuler sa demande</td></tr><tr><td><a href="/IA101/seances/02-contexte-et-boucle-agentique">2</a></td><td>Jeudi 3 décembre</td><td>Contexte et boucle agentique</td></tr><tr><td><a href="/IA101/seances/03-developpement-guide-par-la-spec">3</a></td><td>Lundi 7 décembre</td><td>Développement guidé par la spécification</td></tr><tr><td><a href="/IA101/seances/04-orchestration-et-pratique-pro">4</a></td><td>Jeudi 10 décembre</td><td>Orchestration et pratique professionnelle</td></tr></tbody></table><p>Chaque séance alterne une courte partie théorique avec démonstration et une longue activité pratique.</p><h2 id="le-projet-fil-rouge-jumelo" tabindex="-1">Le projet fil rouge : Jumelo <a class="header-anchor" href="#le-projet-fil-rouge-jumelo" aria-label="Permalink to &quot;Le projet fil rouge : Jumelo&quot;">​</a></h2><p>Toutes les activités se font sur <strong><a href="https://github.com/Cochenille/Jumelo" target="_blank" rel="noreferrer">Jumelo</a></strong>, l&#39;application WPF du Service des stages qui jumelle les finissants avec les offres des entreprises. Une équipe de l&#39;an dernier l&#39;a commencée, puis elle a obtenu son diplôme : <strong>vous la reprenez</strong>. Lisez la mise en situation dans son README avant la première séance.</p><p>Jumelo suit les conventions de vos travaux pratiques : WPF en MVVM avec les classes du cours (<code>ObservableObject</code>, <code>BaseViewModel</code>, <code>RelayCommand</code>), EF Core avec SQLite, tests xUnit et Moq. Vous créez votre propre dépôt à partir du template au début de la séance 1, puis le projet évolue d&#39;une séance à l&#39;autre.</p><h2 id="outils" tabindex="-1">Outils <a class="header-anchor" href="#outils" aria-label="Permalink to &quot;Outils&quot;">​</a></h2><ul><li><strong>GitHub Copilot</strong>, avec la licence gratuite de <a href="https://education.github.com/" target="_blank" rel="noreferrer">GitHub Education</a>.</li><li><strong>Visual Studio 2026</strong> pour le code et les vues XAML, comme dans vos TP.</li><li><strong>VS Code</strong> avec C# Dev Kit, à partir de la séance 2, comme poste de pilotage de l&#39;agent.</li><li><strong>SDK .NET 10</strong> et <strong>Git</strong>.</li></ul><p>Les notions du cours ne dépendent pas de l&#39;outil : ce que vous apprenez avec Copilot s&#39;applique à Claude Code, Cursor, Codex ou aux outils de votre futur employeur.</p><h2 id="evaluation" tabindex="-1">Évaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Évaluation&quot;">​</a></h2><p>Les activités du cours <strong>ne sont pas notées</strong> : ce sont des activités d&#39;apprentissage, faites en classe, dont il reste une trace dans votre dépôt (commits, fichiers, pull requests) pour en discuter. Des <strong>questions sur les notions</strong> des quatre séances feront partie de l&#39;<strong>examen final</strong>.</p>',16)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
